document.addEventListener("DOMContentLoaded",(function(){document.querySelectorAll(".faq-section .section-grid");document.querySelectorAll(".faq-section .grid-item .question").forEach((e=>{e.addEventListener("click",(function(){const t=this.parentElement,s=(t.closest(".section-grid"),t.querySelector(".answer")),l=this.querySelector(".plus-icon"),o=this.querySelector(".minus-icon");if("block"===s.style.display)s.style.display="none",l.style.display="block",o.style.display="none",t.style.height="auto";else{s.style.display="block",l.style.display="none",o.style.display="block";const i=e.offsetHeight+s.offsetHeight+40;t.style.height=i+"px"}}))}))}));